/**
 * @suppress
 */
public object FfiConverterTypeLinkEvent : FfiConverterRustBuffer<LinkEvent>{
    override fun read(buf: ByteBuffer): LinkEvent {
        return when(buf.getInt()) {
            1 -> LinkEvent.Paired(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            2 -> LinkEvent.Connected(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            3 -> LinkEvent.Disconnected(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            4 -> LinkEvent.Text(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            5 -> LinkEvent.DismissRequested(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            6 -> LinkEvent.ReplyRequested(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            7 -> LinkEvent.ActionRequested(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterUInt.read(buf),
                )
            8 -> LinkEvent.ClipboardReceived(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            9 -> LinkEvent.MediaControlRequested(
                FfiConverterString.read(buf),
                FfiConverterTypeMediaCommand.read(buf),
                )
            10 -> LinkEvent.SmsSendRequested(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            11 -> LinkEvent.SmsOlderRequested(
                FfiConverterString.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                )
            12 -> LinkEvent.TransferChanged(
                FfiConverterTypeFileTransfer.read(buf),
                )
            13 -> LinkEvent.RequestResult(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterBoolean.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: LinkEvent): ULong = when(value) {
        is LinkEvent.Paired -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`id`)
                + FfiConverterString.allocationSize(value.`name`)
            )
        }
        is LinkEvent.Connected -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`id`)
